import canonicalMain from '../../customer/test/helpers/delivery-canonical-context.cjs';
import Outreach from '../../customer/outreach-engine.js';
// A real canonical approval generated by the same Strategy contract as the UI.
// This is fixture data, not a runtime fallback or fabricated approval stamp.
export const deliverySourcePayload=()=>({main:canonicalMain(),outreach:{messageStudio:{}}});
export const deliverySourceAuthority=()=>{const p=deliverySourcePayload();return Outreach.messageSourceAuthority(p.main,p.outreach.messageStudio);};
export function seedDeliverySource(DB,workspaceId){const payload=deliverySourcePayload();DB.raw.prepare('DELETE FROM customer_workspace_state WHERE workspace_id=?').run(workspaceId);DB.raw.prepare('INSERT INTO customer_workspace_state(workspace_id,payload_json) VALUES(?,?)').run(workspaceId,JSON.stringify(payload));return {payload,authority:Outreach.messageSourceAuthority(payload.main,payload.outreach.messageStudio)};}

export function seedConversationSource(DB){DB.raw.exec("CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,workspace_id TEXT,user_id TEXT,event_type TEXT,entity_type TEXT,entity_id TEXT,metadata_json TEXT);CREATE TABLE IF NOT EXISTS customer_workspace_state(workspace_id TEXT PRIMARY KEY,payload_json TEXT)");seedDeliverySource(DB,'w1');seedDeliverySource(DB,'w2');}
